/*
 * Map
 */
 
$(document).ready(function(){
    if ($('body').attr('id') != 'walldrugmap')
        return;
    if ($(window).width() > 800)
        var defZoom = 2;
    else
        var defZoom = 1;
        var largeMap = L.map('map', {
          maxZoom: 4,
          minZoom: 1,
          crs: L.CRS.Simple,
          attributionControl: false,
          zoomControl: false,
        }).setView([0, 0], defZoom);
        largeMap.addControl(L.control.zoom({ position: 'bottomright' }))
        L.tileLayer('assets/images/uploads/map/%7bz%7d/%7bx%7d/%7by%7d.jpg/index.html', {
            minZoom: 1, maxZoom: 4, continuousWorld: true, tms: true
        }).addTo(largeMap);
        var southWest  = largeMap.unproject([0, 0], largeMap.getMaxZoom());
        var northEast = largeMap.unproject([3534, -3331], largeMap.getMaxZoom());
        largeMap.setMaxBounds(new L.LatLngBounds(southWest, northEast));
});
$.fn.animateRotate = function(angle, duration, easing, complete) {
  var args = $.speed(duration, easing, complete);
  var step = args.step;
  return this.each(function(i, e) {
    args.complete = $.proxy(args.complete, e);
    args.step = function(now) {
      $.style(e, 'transform', 'rotate(' + now + 'deg)');
      if (step) return step.apply(e, arguments);
    };
    $({deg: 0}).animate({deg: angle}, args);
  });
};

/*
 * Social feed (converse)
 */
 
$(window).on('load', function(){
  var $social_feed = $('.social-feed');
  if ($social_feed.length < 1)
  	return;
  var sfHas = 0;
  var sfPage = 0;
  $(window).scroll(function(){
	if (sfHas == 1)
	    return;
    if ($social_feed.is(':visible')) {
		sfHas = 1;
		$('#social-load-img').animateRotate(90);
        $.ajax({
            url: "/converse/page/" + sfPage,
            success: function(response){
                $social_feed.append(response);
            },
        });
		sfPage++;
	 }
  }).scroll();
  
  $('#social-load').click(function(){
    sfHas = 1;
    $('#social-load-img').animateRotate(90);
        $.ajax({
            url: "/converse/page/" + sfPage,
            success: function(response){
//				var x = $('response');
                $social_feed.append(response);
//                $social_feed.delay(1000).masonry('reload');
            },
        });
    sfPage++;    
  });
});

